// The parameter manifest and provenance files of an image (generated by tools/gen/params_gen.py, served by the helper at
// /api/images/<hash>/params_manifest and /params_provenance). Parsing is strict about what the GUI relies on and says what is wrong.
import type { Method, Origin, SigmaKind } from '$link/vehicle';
import type { ParamType } from '$link/bits';

export interface ManifestParam {
	/** The full name. */
	name: string;
	id: number;
	type: ParamType;
	unit: string;
	linkId: string;
	locked: boolean;
	defaultBits: number;
	method: Method;
	sigmaKind: SigmaKind;
	sigma: number;
	origin: Origin;
	source: string;
	sourceFile: string;
}

export interface Manifest {
	schemaHash: string;
	count: number;
	/** In id order. */
	params: ManifestParam[];
}

export interface LockInfo {
	by: string;
	on: string;
	via: string;
}

export interface ProvenanceEntry {
	name: string;
	sourceFile: string;
	shape: string | null;
	components: string[];
	lock: LockInfo | null;
}

export interface Provenance {
	schemaHash: string;
	entries: ProvenanceEntry[];
}

const METHODS = ['published', 'measured', 'identified', 'datasheet', 'derived', 'design-budget', 'scenario'];
const ORIGINS = ['DefaultFromCard', 'DefaultFromRegister', 'Manual', 'Identified'];
const SIGMA_KINDS = ['Known', 'Exact', 'Unknown', 'Choice'];

type Json = Record<string, unknown>;
const isObject = (x: unknown): x is Json => typeof x === 'object' && x !== null && !Array.isArray(x);

function field<T>(obj: Json, key: string, check: (v: unknown) => v is T, where: string): T {
	const v = obj[key];
	if (!check(v)) throw new Error(`${where}: ${key} is missing or of the wrong type`);
	return v;
}
const isString = (v: unknown): v is string => typeof v === 'string';
const isNumber = (v: unknown): v is number => typeof v === 'number' && Number.isFinite(v);
const isBool = (v: unknown): v is boolean => typeof v === 'boolean';

function oneOf<T extends string>(value: string, allowed: string[], where: string, key: string): T {
	if (!allowed.includes(value)) throw new Error(`${where}: ${key} "${value}" is not one of ${allowed.join(', ')}`);
	return value as T;
}

export function parseManifest(json: unknown): Manifest {
	if (!isObject(json)) throw new Error('manifest: not an object');
	const schemaHash = field(json, 'schema_hash', isString, 'manifest');
	const count = field(json, 'count', isNumber, 'manifest');
	const raw = json.params;
	if (!isObject(raw)) throw new Error('manifest: params is missing');
	const params: ManifestParam[] = Object.entries(raw).map(([name, value]) => {
		const where = `manifest param ${name}`;
		if (!isObject(value)) throw new Error(`${where}: not an object`);
		const type = field(value, 'type', isString, where);
		if (type !== 'f32' && type !== 'i32') throw new Error(`${where}: type ${type} is neither f32 nor i32`);
		const defaultBits = Number(field(value, 'default_bits', isString, where));
		if (!Number.isInteger(defaultBits) || defaultBits < 0 || defaultBits > 0xffffffff) throw new Error(`${where}: default_bits is not a 32-bit pattern`);
		return {
			name,
			id: field(value, 'id', isNumber, where),
			type,
			unit: field(value, 'unit', isString, where),
			linkId: field(value, 'link_id', isString, where),
			locked: field(value, 'lock', isBool, where),
			defaultBits,
			method: oneOf<Method>(field(value, 'method', isString, where), METHODS, where, 'method'),
			sigmaKind: oneOf<SigmaKind>(field(value, 'sigma_kind', isString, where), SIGMA_KINDS, where, 'sigma_kind'),
			sigma: field(value, 'sigma', isNumber, where),
			origin: oneOf<Origin>(field(value, 'origin', isString, where), ORIGINS, where, 'origin'),
			source: field(value, 'source', isString, where),
			sourceFile: field(value, 'source_file', isString, where)
		};
	});
	params.sort((a, b) => a.id - b.id);
	if (params.length !== count) throw new Error(`manifest: count is ${count} but ${params.length} parameters are listed`);
	return { schemaHash: schemaHash.toLowerCase(), count, params };
}

export function parseProvenance(json: unknown): Provenance {
	if (!isObject(json)) throw new Error('provenance: not an object');
	const schemaHash = field(json, 'schema_hash', isString, 'provenance');
	const list = json.entries;
	if (!Array.isArray(list)) throw new Error('provenance: entries is missing');
	const entries = list.map((e, i): ProvenanceEntry => {
		const where = `provenance entry ${i}`;
		if (!isObject(e)) throw new Error(`${where}: not an object`);
		const lock = e.lock;
		return {
			name: field(e, 'name', isString, where),
			sourceFile: field(e, 'source_file', isString, where),
			shape: typeof e.shape === 'string' ? e.shape : null,
			components: field(e, 'components', (v): v is string[] => Array.isArray(v) && v.every(isString), where),
			lock: isObject(lock) ? { by: String(lock.by ?? ''), on: String(lock.on ?? ''), via: String(lock.via ?? '') } : null
		};
	});
	return { schemaHash: schemaHash.toLowerCase(), entries };
}
